def test_decode_bounds_each_integer_conversion(monkeypatch):
    conversions = []

    def bounded_int(value):
        assert len(value.lstrip("-")) <= 8
        conversions.append(value)
        return int(value)

    # Exercise the conversion bound even on legacy Python without the digit cap.
    monkeypatch.setattr(domain, "int", bounded_int, raising=False)
    decoded = decode_json(
        b'{"min":1,"max":31536000,"negative":-31536000,"large":' +
        b"9" * 4301 + b',"small":-' + b"9" * 4301 + b"}"
    )
    assert conversions == ["1", "31536000", "-31536000"]
    assert (decoded["min"], decoded["max"], decoded["negative"]) == (1, 31536000, -31536000)


